-- ====================================================================
-- ESQUEMA DDL ACTUALIZADO PARA SUPABASE (POSTGRESQL)
-- MODELO SEGÚN DIAGRAMA UML DE CLASES (pkg)
-- ====================================================================
-- Ejecutar en el SQL Editor de Supabase.

-- 1. Entidad: Usuario
CREATE TABLE IF NOT EXISTS "Usuario" (
    "idUsuario" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "nombre" TEXT NOT NULL,
    "email" TEXT NOT NULL UNIQUE,
    "password" TEXT NOT NULL
);

-- 2. Entidad: Autor
CREATE TABLE IF NOT EXISTS "Autor" (
    "idAutor" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "nombre" TEXT NOT NULL UNIQUE
);

-- 3. Entidad: Editorial
CREATE TABLE IF NOT EXISTS "Editorial" (
    "idEditorial" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "nombre" TEXT NOT NULL UNIQUE
);

-- 4. Entidad: Genero
CREATE TABLE IF NOT EXISTS "Genero" (
    "idGenero" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "nombre" TEXT NOT NULL UNIQUE
);

-- 5. Entidad: Libro (Catálogo fijo de exactamente 100 libros con nroPaginas)
CREATE TABLE IF NOT EXISTS "Libro" (
    "idLibro" INT PRIMARY KEY CHECK ("idLibro" >= 1 AND "idLibro" <= 100),
    "titulo" TEXT NOT NULL,
    "descripcion" TEXT,
    "nroPaginas" INT NOT NULL CHECK ("nroPaginas" > 0),
    "precio" NUMERIC(10, 2) NOT NULL CHECK ("precio" >= 0),
    "idAutor" BIGINT NOT NULL REFERENCES "Autor"("idAutor") ON UPDATE CASCADE ON DELETE RESTRICT,
    "idEditorial" BIGINT NOT NULL REFERENCES "Editorial"("idEditorial") ON UPDATE CASCADE ON DELETE RESTRICT
);

-- 6. Trigger para reforzar la regla de negocio: Máximo 100 libros en el catálogo
CREATE OR REPLACE FUNCTION check_limite_100_libros()
RETURNS TRIGGER AS $$
BEGIN
    IF (SELECT COUNT(*) FROM "Libro") >= 100 THEN
        RAISE EXCEPTION 'Regla de Negocio: El catálogo tiene un límite estricto de exactamente 100 libros.';
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_limite_catalogo_100_libros ON "Libro";
CREATE TRIGGER trg_limite_catalogo_100_libros
BEFORE INSERT ON "Libro"
FOR EACH ROW
EXECUTE FUNCTION check_limite_100_libros();

-- 7. Entidad: Preferencia (Interacciones explícitas e implícitas)
CREATE TABLE IF NOT EXISTS "Preferencia" (
    "idPreferencia" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "rating" INT CHECK ("rating" IS NULL OR ("rating" >= 1 AND "rating" <= 5)),
    "fecha" DATE DEFAULT CURRENT_DATE,
    "idUsuario" BIGINT NOT NULL REFERENCES "Usuario"("idUsuario") ON UPDATE CASCADE ON DELETE CASCADE,
    "idLibro" INT NOT NULL REFERENCES "Libro"("idLibro") ON UPDATE CASCADE ON DELETE CASCADE
);

-- 8. Tabla Intermedia: GeneroLibro (Relación N:M)
CREATE TABLE IF NOT EXISTS "GeneroLibro" (
    "idGenero" BIGINT NOT NULL REFERENCES "Genero"("idGenero") ON UPDATE CASCADE ON DELETE CASCADE,
    "idLibro" INT NOT NULL REFERENCES "Libro"("idLibro") ON UPDATE CASCADE ON DELETE CASCADE,
    PRIMARY KEY ("idGenero", "idLibro")
);

-- 9. Tabla Intermedia: UsuarioGenero (Onboarding / Cold Start, con multiplicidad 0..3)
CREATE TABLE IF NOT EXISTS "UsuarioGenero" (
    "idPreferencia" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "idUsuario" BIGINT NOT NULL REFERENCES "Usuario"("idUsuario") ON UPDATE CASCADE ON DELETE CASCADE,
    "idGenero" BIGINT NOT NULL REFERENCES "Genero"("idGenero") ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT uq_usuario_genero UNIQUE ("idUsuario", "idGenero")
);

-- 10. Trigger para garantizar la multiplicidad 0..3 (máximo 3 géneros por usuario)
CREATE OR REPLACE FUNCTION check_limite_usuario_genero()
RETURNS TRIGGER AS $$
BEGIN
    IF (SELECT COUNT(*) FROM "UsuarioGenero" WHERE "idUsuario" = NEW."idUsuario") >= 3 THEN
        RAISE EXCEPTION 'Regla de Negocio: Un usuario no puede seleccionar más de 3 géneros favoritos (multiplicidad 0..3).';
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_limite_usuario_genero ON "UsuarioGenero";
CREATE TRIGGER trg_limite_usuario_genero
BEFORE INSERT ON "UsuarioGenero"
FOR EACH ROW
EXECUTE FUNCTION check_limite_usuario_genero();

-- ====================================================================
-- ÍNDICES DE RENDIMIENTO PARA EL SISTEMA RECOMENDADOR
-- ====================================================================
CREATE INDEX IF NOT EXISTS idx_preferencia_usuario ON "Preferencia"("idUsuario");
CREATE INDEX IF NOT EXISTS idx_preferencia_libro ON "Preferencia"("idLibro");
CREATE INDEX IF NOT EXISTS idx_preferencia_user_item ON "Preferencia"("idUsuario", "idLibro");
CREATE INDEX IF NOT EXISTS idx_generolibro_genero ON "GeneroLibro"("idGenero");
CREATE INDEX IF NOT EXISTS idx_generolibro_libro ON "GeneroLibro"("idLibro");
CREATE INDEX IF NOT EXISTS idx_usuariogenero_user ON "UsuarioGenero"("idUsuario");
CREATE INDEX IF NOT EXISTS idx_libro_autor ON "Libro"("idAutor");
CREATE INDEX IF NOT EXISTS idx_libro_editorial ON "Libro"("idEditorial");

-- ====================================================================
-- SEGURIDAD: ROW LEVEL SECURITY (RLS)
-- ====================================================================
ALTER TABLE "Usuario" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "Autor" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "Editorial" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "Genero" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "Libro" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "Preferencia" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "GeneroLibro" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "UsuarioGenero" ENABLE ROW LEVEL SECURITY;

-- Políticas de lectura pública para el catálogo
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'Lectura pública catálogo libros') THEN
        CREATE POLICY "Lectura pública catálogo libros" ON "Libro" FOR SELECT USING (true);
        CREATE POLICY "Lectura pública autores" ON "Autor" FOR SELECT USING (true);
        CREATE POLICY "Lectura pública editoriales" ON "Editorial" FOR SELECT USING (true);
        CREATE POLICY "Lectura pública generos" ON "Genero" FOR SELECT USING (true);
        CREATE POLICY "Lectura pública genero_libro" ON "GeneroLibro" FOR SELECT USING (true);
    END IF;
END $$;

-- Políticas de acceso completo para service_role (Carga y Backend)
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'Service role total access all libros') THEN
        CREATE POLICY "Service role total access all libros" ON "Libro" FOR ALL USING (true);
        CREATE POLICY "Service role total access all autores" ON "Autor" FOR ALL USING (true);
        CREATE POLICY "Service role total access all editoriales" ON "Editorial" FOR ALL USING (true);
        CREATE POLICY "Service role total access all generos" ON "Genero" FOR ALL USING (true);
        CREATE POLICY "Service role total access all genero_libro" ON "GeneroLibro" FOR ALL USING (true);
        CREATE POLICY "Service role total access all usuarios" ON "Usuario" FOR ALL USING (true);
        CREATE POLICY "Service role total access all preferencias" ON "Preferencia" FOR ALL USING (true);
        CREATE POLICY "Service role total access all usuariogenero" ON "UsuarioGenero" FOR ALL USING (true);
    END IF;
END $$;

-- ====================================================================
-- PERMISOS DE ESQUEMA Y TABLAS PARA ROLES DE SUPABASE
-- ====================================================================
GRANT USAGE ON SCHEMA public TO postgres, anon, authenticated, service_role;
GRANT ALL ON ALL TABLES IN SCHEMA public TO postgres, anon, authenticated, service_role;
GRANT ALL ON ALL SEQUENCES IN SCHEMA public TO postgres, anon, authenticated, service_role;
GRANT ALL ON ALL ROUTINES IN SCHEMA public TO postgres, anon, authenticated, service_role;

ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT ALL ON TABLES TO postgres, anon, authenticated, service_role;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT ALL ON SEQUENCES TO postgres, anon, authenticated, service_role;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT ALL ON ROUTINES TO postgres, anon, authenticated, service_role;
